KG42.register("nodes-7f8226163ee58dd6b2adb3d5",{"id":"COMP-aca52f9d7c02a0d7","code":"CLR048","label":"Capacity, balance and operating-mode conditions for active and reactive exchange at grid connection","definition":"The MG PCC exchanges P_{jt} and Q_{jt} are constrained by capacity limits and by Σ_kP_{kt}=D^P_{jt}+P_{jt} and Σ_kQ_{kt}=D^Q_{jt}+Q_{jt}. A negative active-power value denotes purchase and a positive value denotes outward delivery. Case2 scales the upper and lower bounds of the source expressions P_{it} and Q_{it} (i∈J) by ρ_{jt}∈{0,1}; when ρ_{jt}=0, the exchange is zero.","layer":"L5","template_code":"PGR","concept_id":"execution.energy_trade","concept_ids":["execution.energy_trade"],"identity_dimensions":{"identity_fields":["Object: active- and reactive-power exchange quantities at the grid boundary","Core relation: the exchange quantities simultaneously satisfy local generation-consumption balance and the boundary capacity conditions","Mode relation: the binary operating mode controls the feasible range of exchange","Output: PCC exchange quantities satisfying the constraints"]},"exclusions":["Interface entities: MG and DS; interface location: PCC","Balance inputs: MG-internal DG output and active- and reactive-power load","Active-power sign: import is negative and export is positive","Case2 extension: grid-connected and islanded switching","The mode constraint retains the index notation of the source expressions ρ_{jt} and i∈J","Capacity and operating-mode conditions belong to the optimization model"],"members":[{"id":"35-microgrid_pool_strategy::v141-c-R002::V::execution.energy_trade","rule_id":"v141-c-R002","market_meaning":"Actual DEM distribution locational marginal prices provide feedback to microgrid demand bids. Scope: Microgrid demand bidding within the modeled distribution electricity market. A microgrid can submit demand bids to the distribution market operator when it imports power from the distribution system. Scope: Microgrid demand-bid submission to the distribution market operator. Condition: When the microgrid extracts power from the distribution system. DS spot loads bid with forecast market prices. Scope: DS spot-load demand bids under the paper's market-model assumptions. Customer demand bids use linearized bidding curves. Scope: Bidding curves for all customers in the modeled distribution electricity market.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Bidding curves for all customers in the modeled distribution electricity market. | DS spot-load demand bids under the paper's market-model assumptions. | Microgrid demand bidding within the modeled distribution electricity market. | Microgrid demand-bid submission to the distribution market operator.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E06","v141-b-g02-E04","v141-b-g02-E26","v141-b-g02-E28"]},"constraint_refs":["35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C002","35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C005","35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C006"],"decision_anchor":"bidding.demand","source_rule_sha256":"0e7195e0a97e2b73852ba7652d7278f920abcc4e3ed16c119029927102ade7c1","paper":"35-microgrid_pool_strategy","rule_ref":"35-microgrid_pool_strategy::v141-c-R002","node_id":"execution.energy_trade","function":"execution.energy_trade","unit_id":"35-microgrid_pool_strategy::v141-a-M01::execution.energy_trade","mechanism_id":"v141-a-M01","anchor":false},{"id":"35-microgrid_pool_strategy::v141-c-R008::V::execution.energy_trade","rule_id":"v141-c-R008","market_meaning":"The local distribution-system market-clearing model restricts PCC power exchanges to its feasible set, including exchange capacity bounds. Scope: MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM. Real and reactive MG power balances must ensure that DG generation supplies the entire load and the power exchange at the PCC. Scope: MG real and reactive power balances governing exchanges at the PCC. Both real and reactive MG exchange bounds are scaled by the binary variable controlling the working-mode switch. Scope: MG–DS real and reactive power exchanges in Case2. Condition: Case2 contingency study of switching between grid-connected and islanded operation.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"MG real and reactive power balances governing exchanges at the PCC. | MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM. | MG–DS real and reactive power exchanges in Case2.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12","v141-b-g01-E18","v141-b-g02-E43"]},"constraint_refs":["35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C001","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C002","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C003"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"9dbdad892119e2a8938c0b6981b142d00ffe8b590eff062b80682069a97b144e","paper":"35-microgrid_pool_strategy","rule_ref":"35-microgrid_pool_strategy::v141-c-R008","node_id":"execution.energy_trade","function":"execution.energy_trade","unit_id":"35-microgrid_pool_strategy::v141-a-M01::execution.energy_trade","mechanism_id":"v141-a-M01","anchor":true}],"paper_ids":["35-microgrid_pool_strategy"],"evidence":[{"evidence_id":"v141-b-g02-E26","location":{"location_id":"src-169a788abb-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"1) be solved by using some commercial software packages. The MIP formulation is as follows: min δGit","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The microgrid is prosumer such that (1) it can submit offers to the distribution market operator when it exports power to the DS or (2) it can submit bids to the distribution market operator when it extracts power from the DS. The bidding/offering prices for MGs in bi-level model always coincide with DLMPs.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R002","quote":"The microgrid is prosumer such that (1) it can submit offers to the distribution market operator when it exports power to the DS or (2) it can submit bids to the distribution market operator when it extracts power from the DS. The bidding/offering prices for MGs in bi-level model always coincide with DLMPs."},{"evidence_id":"v141-b-g02-E32","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"4) Bidding Strategy: 5) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}\u003c\\lambda^{P}_{bt}, it indicates that the MG j-th is extracting power from DS with higher cost even though it has a cheap power source available inside. Then we set \\alpha'_{jt}=\\beta_{jt} to maintain the profitability of MG j-th.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R002","quote":"4) Bidding Strategy: 5) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}\u003c\\lambda^{P}_{bt}, it indicates that the MG j-th is extracting power from DS with higher cost even though it has a cheap power source available inside. Then we set \\alpha'_{jt}=\\beta_{jt} to maintain the profitability of MG j-th."},{"evidence_id":"v141-b-g02-E41","location":{"location_id":"src-169a788abb-p08-c1r1__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"10 TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY Fi TABLE III COMPARISONS OF MG BIDDING/","equation_id":null,"figure_id":null,"table_id":"Table II","image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY. Columns: j, t, \\lambda^{P}_{bt} ($/p.u.), P_{jt} (p.u.), \\alpha_{jt} ($/p.u.), \\beta_{jt} ($/p.u.), \\alpha'_{jt} ($/p.u.). Rows: j=1,t=10, \\lambda^{P}_{bt}=0.44, P_{jt}=-0.024, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.44+\\varepsilon; j=2,t=21, \\lambda^{P}_{bt}=0.91, P_{jt}=-0.047, \\alpha_{jt}=0.91, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5; j=2,t=14, \\lambda^{P}_{bt}=0.66, P_{jt}=0.026, \\alpha_{jt}=0.66, \\beta_{jt}=0.5, \\alpha'_{jt}=0.66-\\varepsilon; j=3,t=3, \\lambda^{P}_{bt}=0.44, P_{jt}=0.022, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R002","quote":"TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY. Columns: j, t, \\lambda^{P}_{bt} ($/p.u.), P_{jt} (p.u.), \\alpha_{jt} ($/p.u.), \\beta_{jt} ($/p.u.), \\alpha'_{jt} ($/p.u.). Rows: j=1,t=10, \\lambda^{P}_{bt}=0.44, P_{jt}=-0.024, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.44+\\varepsilon; j=2,t=21, \\lambda^{P}_{bt}=0.91, P_{jt}=-0.047, \\alpha_{jt}=0.91, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5; j=2,t=14, \\lambda^{P}_{bt}=0.66, P_{jt}=0.026, \\alpha_{jt}=0.66, \\beta_{jt}=0.5, \\alpha'_{jt}=0.66-\\varepsilon; j=3,t=3, \\lambda^{P}_{bt}=0.44, P_{jt}=0.022, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5."},{"evidence_id":"v141-b-g02-E33","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"6) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}>\\lambda^{P}_{bt}, it indicates that MG j-th is extracting power from DS rather than generating power itself with higher cost. Then MG will bid with price \\alpha'_{jt}=\\lambda^{P}_{bt}+\\varepsilon. The decreasing bid can encourage DS to export more power to MG j-th.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R002","quote":"6) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}>\\lambda^{P}_{bt}, it indicates that MG j-th is extracting power from DS rather than generating power itself with higher cost. Then MG will bid with price \\alpha'_{jt}=\\lambda^{P}_{bt}+\\varepsilon. The decreasing bid can encourage DS to export more power to MG j-th."},{"evidence_id":"v141-b-g02-E34","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"It is noted that \\varepsilon is a very small positive constant, e.g., 10^{-5}.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R002","quote":"It is noted that \\varepsilon is a very small positive constant, e.g., 10^{-5}."},{"evidence_id":"v141-b-g02-E42","location":{"location_id":"src-169a788abb-p08-c1r4__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"The DLMP (λPbt) and marginal cost (βjt) and the power ex- th change between MG and DS (Pjt) are give","equation_id":null,"figure_id":null,"table_id":"Table II","image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"The MG1 at 10:00 am extracts power from DS. \\beta_{1,10}>\\lambda^{P}_{30,10}, the bid with decreasing price is 0.44+\\varepsilon. For MG2 at 21:00 pm, \\beta_{2,21}\u003c\\lambda^{P}_{13,21}, the fix offer is 0.5 to maintain its profit. For MG2 at 14:00 pm, \\beta_{2,14}\u003c\\lambda^{P}_{13,14}, the increasing offer is 0.66-\\varepsilon. For MG3 at 3:00 am, the \\beta_{3,3}>\\lambda^{P}_{21,3}, the fixed offer price is set at 0.5.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R002","quote":"The MG1 at 10:00 am extracts power from DS. \\beta_{1,10}>\\lambda^{P}_{30,10}, the bid with decreasing price is 0.44+\\varepsilon. For MG2 at 21:00 pm, \\beta_{2,21}\u003c\\lambda^{P}_{13,21}, the fix offer is 0.5 to maintain its profit. For MG2 at 14:00 pm, \\beta_{2,14}\u003c\\lambda^{P}_{13,14}, the increasing offer is 0.66-\\varepsilon. For MG3 at 3:00 am, the \\beta_{3,3}>\\lambda^{P}_{21,3}, the fixed offer price is set at 0.5."},{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-pricing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The DLMPs (λPbt) are endogenously generated from the lower-level programming model (8)–(16) (LLPM), and the MG uses DLMPs as the base bidding/offering price λPb′jt. The real power and reactive power exchange at PCC belong to the feasible set defined by the LLPM as in constraint (8).","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"The DLMPs (λPbt) are endogenously generated from the lower-level programming model (8)–(16) (LLPM), and the MG uses DLMPs as the base bidding/offering price λPb′jt. The real power and reactive power exchange at PCC belong to the feasible set defined by the LLPM as in constraint (8)."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-169a788abb-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"p p g g the feasible set deﬁned by the LLPM as in constraint (8). The LLPM presents the distribution","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The LLPM presents the distribution system market clearing problem with the objective to maximize the social welfare (8), which consists of four terms. The first three terms represent the total cost for the DS: operation cost from DS-owned DGs, power exchange with MG, and the cost of extracting power from utility power system. The last item is total benefits obtained by supplying power to customers. Constraint (9) and (10) guarantee that the DGs’ outputs, MGs power exchange, utility extraction, and load requirement are within a capacity range. The constraints (11)–(16) are DistFlow equations that can be used to describe the complex power flows at each node for DS. Constraints (11) and (12) are real power injection and reactive power injection at each node.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"The LLPM presents the distribution system market clearing problem with the objective to maximize the social welfare (8), which consists of four terms. The first three terms represent the total cost for the DS: operation cost from DS-owned DGs, power exchange with MG, and the cost of extracting power from utility power system. The last item is total benefits obtained by supplying power to customers. Constraint (9) and (10) guarantee that the DGs’ outputs, MGs power exchange, utility extraction, and load requirement are within a capacity range. The constraints (11)–(16) are DistFlow equations that can be used to describe the complex power flows at each node for DS. Constraints (11) and (12) are real power injection and reactive power injection at each node."},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-169a788abb-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"j m l ce. ar- P itmin ≤Pit ≤P itmax : μpitmin , μpitmax , e if ∀t, ∀i ∈J, L, M, N (9) al- Qmin it ≤Q","equation_id":"Eqs. (9)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"P^{min}_{it} \\le P_{it} \\le P^{max}_{it} : \\mu^{p min}_{it}, \\mu^{p max}_{it}, \\forall t, \\forall i \\in J,L,M,N (9) \\quad Q^{min}_{it} \\le Q_{it} \\le Q^{max}_{it} : \\mu^{q min}_{(.)t}, \\mu^{q max}_{(.)t}, \\forall t, \\forall i \\in J,L,M,N (10)","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"P^{min}_{it} \\le P_{it} \\le P^{max}_{it} : \\mu^{p min}_{it}, \\mu^{p max}_{it}, \\forall t, \\forall i \\in J,L,M,N (9) \\quad Q^{min}_{it} \\le Q_{it} \\le Q^{max}_{it} : \\mu^{q min}_{(.)t}, \\mu^{q max}_{(.)t}, \\forall t, \\forall i \\in J,L,M,N (10)"},{"evidence_id":"v141-b-g01-E18","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The objective function of the upper level programming model (ULPM) is to minimize power generation cost of microgrids, power exchange cost at point of common coupling and load shedding cost. The power exchange cost is negative when MGs are extracting power from the distribution system or positive when MGs are exporting power to the DS. Dispatchable generators in MG are subject to real power output capacity constraint (2), reactive power capacity output constraint (3), ramp up rate (4) and ramp down rate (5). Real power balance equations (6) and reactive power balance equations (7) together ensure that the power generated by DGs is used to supply the entire load and the power exchange at PCC.","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"The objective function of the upper level programming model (ULPM) is to minimize power generation cost of microgrids, power exchange cost at point of common coupling and load shedding cost. The power exchange cost is negative when MGs are extracting power from the distribution system or positive when MGs are exporting power to the DS. Dispatchable generators in MG are subject to real power output capacity constraint (2), reactive power capacity output constraint (3), ramp up rate (4) and ramp down rate (5). Real power balance equations (6) and reactive power balance equations (7) together ensure that the power generated by DGs is used to supply the entire load and the power exchange at PCC."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-169a788abb-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 35, NO. 1, JANUARY 2020 our Pkt = DPjt + Pjt, ∀t, ∀k ∈Kj, ∀","equation_id":"Eqs. (6)-(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\sum_k P_{kt} = D^P_{jt} + P_{jt}, \\forall t, \\forall k \\in K_j, \\forall j \\in J (6) \\quad \\sum_k Q_{kt} = D^Q_{jt} + Q_{jt}, \\forall t, k \\in K_j, \\forall j \\in J (7)","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"\\sum_k P_{kt} = D^P_{jt} + P_{jt}, \\forall t, \\forall k \\in K_j, \\forall j \\in J (6) \\quad \\sum_k Q_{kt} = D^Q_{jt} + Q_{jt}, \\forall t, k \\in K_j, \\forall j \\in J (7)"},{"evidence_id":"v141-b-g02-E43","location":{"location_id":"src-169a788abb-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"ads p p p p y p , and especially in the infancy of MG industry deployment. G3 Case2:Thiscasestudiest","equation_id":"Eqs. (54)-(56)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T-\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours. \\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le\\rho_{jt}P_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (54)\\\\ \\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le\\rho_{jt}Q_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (55)\\\\ \\sum_t \\rho_{jt}=T-\\tau\\ \\ \\forall i\\in J \\quad (56)","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T-\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours. \\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le\\rho_{jt}P_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (54)\\\\ \\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le\\rho_{jt}Q_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (55)\\\\ \\sum_t \\rho_{jt}=T-\\tau\\ \\ \\forall i\\in J \\quad (56)"},{"evidence_id":"v141-b-g03-e003","location":{"location_id":"src-169a788abb-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"10","section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"ads p p p p y p , and especially in the infancy of MG industry deployment. G3 Case2:Thiscasestudiest","equation_id":"Eqs. (54)-(56)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T -\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours.\n\\rho_{jt}P_{it}^{\\min} \\le P_{it} \\le \\rho_{jt}P_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{54}\n\\rho_{jt}Q_{it}^{\\min} \\le Q_{it} \\le \\rho_{jt}Q_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{55}\n\\sum_{t}\\rho_{jt}=T-\\tau \\quad \\forall i \\in J \\tag{56}","paper":"35-microgrid_pool_strategy","rule_id":"v141-c-R008","quote":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T -\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours.\n\\rho_{jt}P_{it}^{\\min} \\le P_{it} \\le \\rho_{jt}P_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{54}\n\\rho_{jt}Q_{it}^{\\min} \\le Q_{it} \\le \\rho_{jt}Q_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{55}\n\\sum_{t}\\rho_{jt}=T-\\tau \\quad \\forall i \\in J \\tag{56}"}],"candidate_only":true,"classification_subtypes":["pcc_exchange_feasibility"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L5-6aa11108aa","secondary_families":[],"stage":"L5","ontological_kind":"pcc_exchange_feasibility"},"semantic_definition":{},"source_units":[{"unit_id":"35-microgrid_pool_strategy::v141-a-M01::execution.energy_trade","paper_id":"35-microgrid_pool_strategy","mechanism_id":"v141-a-M01","function":"execution.energy_trade","source_occurrences":[{"id":"35-microgrid_pool_strategy::v141-c-R002::V::execution.energy_trade","rule_id":"v141-c-R002","market_meaning":"Actual DEM distribution locational marginal prices provide feedback to microgrid demand bids. Scope: Microgrid demand bidding within the modeled distribution electricity market. A microgrid can submit demand bids to the distribution market operator when it imports power from the distribution system. Scope: Microgrid demand-bid submission to the distribution market operator. Condition: When the microgrid extracts power from the distribution system. DS spot loads bid with forecast market prices. Scope: DS spot-load demand bids under the paper's market-model assumptions. Customer demand bids use linearized bidding curves. Scope: Bidding curves for all customers in the modeled distribution electricity market.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Bidding curves for all customers in the modeled distribution electricity market. | DS spot-load demand bids under the paper's market-model assumptions. | Microgrid demand bidding within the modeled distribution electricity market. | Microgrid demand-bid submission to the distribution market operator.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E06","v141-b-g02-E04","v141-b-g02-E26","v141-b-g02-E28"]},"constraint_refs":["35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C002","35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C005","35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C006"],"decision_anchor":"bidding.demand","source_rule_sha256":"0e7195e0a97e2b73852ba7652d7278f920abcc4e3ed16c119029927102ade7c1"},{"id":"35-microgrid_pool_strategy::v141-c-R008::V::execution.energy_trade","rule_id":"v141-c-R008","market_meaning":"The local distribution-system market-clearing model restricts PCC power exchanges to its feasible set, including exchange capacity bounds. Scope: MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM. Real and reactive MG power balances must ensure that DG generation supplies the entire load and the power exchange at the PCC. Scope: MG real and reactive power balances governing exchanges at the PCC. Both real and reactive MG exchange bounds are scaled by the binary variable controlling the working-mode switch. Scope: MG–DS real and reactive power exchanges in Case2. Condition: Case2 contingency study of switching between grid-connected and islanded operation.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"MG real and reactive power balances governing exchanges at the PCC. | MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM. | MG–DS real and reactive power exchanges in Case2.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12","v141-b-g01-E18","v141-b-g02-E43"]},"constraint_refs":["35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C001","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C002","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C003"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"9dbdad892119e2a8938c0b6981b142d00ffe8b590eff062b80682069a97b144e"}],"constraints":[{"constraint_id":"v141-c-R002-C002","kind":"logical","role":"core","statement":"A microgrid can submit demand bids to the distribution market operator when it imports power from the distribution system. Scope: Microgrid demand-bid submission to the distribution market operator. Condition: When the microgrid extracts power from the distribution system.","expression":"P_j^{\\min} \\le P_{jt} \u003c 0","formalization_origin":"source","template_id":null,"members":["bidding.demand","execution.energy_trade"],"variable_refs":["v141-c-R002-x-Pjt"],"parameter_refs":["v141-c-R002-theta-Pjmin"],"evidence_ids":["v141-b-g02-E26","v141-b-g02-E32"],"ref":"35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C002","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g02-E26","location":{"location_id":"src-169a788abb-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"1) be solved by using some commercial software packages. The MIP formulation is as follows: min δGit","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The microgrid is prosumer such that (1) it can submit offers to the distribution market operator when it exports power to the DS or (2) it can submit bids to the distribution market operator when it extracts power from the DS. The bidding/offering prices for MGs in bi-level model always coincide with DLMPs."},{"evidence_id":"v141-b-g02-E32","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"4) Bidding Strategy: 5) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}\u003c\\lambda^{P}_{bt}, it indicates that the MG j-th is extracting power from DS with higher cost even though it has a cheap power source available inside. Then we set \\alpha'_{jt}=\\beta_{jt} to maintain the profitability of MG j-th."}]},{"constraint_id":"v141-c-R002-C005","kind":"mathematical","role":"supporting","statement":"For an extracting microgrid (P_j^{min} \u003c= P_{jt} \u003c 0) with marginal cost below the DLMP (beta_jt \u003c lambda^P_bt), the modified demand bid price is set equal to its marginal cost.","expression":"\\alpha'_{jt}=\\beta_{jt}, \\quad \\text{for } P_j^{\\min}\\le P_{jt}\u003c0 \\text{ and } \\beta_{jt}\u003c\\lambda^{P}_{bt}","formalization_origin":"source","template_id":null,"members":["bidding.demand","pricing.local","execution.energy_trade"],"variable_refs":["v141-c-R002-x-alpha-prime","v141-c-R002-x-Pjt"],"parameter_refs":["v141-c-R002-theta-beta","v141-c-R002-theta-lambda","v141-c-R002-theta-Pjmin"],"evidence_ids":["v141-b-g02-E32","v141-b-g02-E41"],"ref":"35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C005","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g02-E32","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"4) Bidding Strategy: 5) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}\u003c\\lambda^{P}_{bt}, it indicates that the MG j-th is extracting power from DS with higher cost even though it has a cheap power source available inside. Then we set \\alpha'_{jt}=\\beta_{jt} to maintain the profitability of MG j-th."},{"evidence_id":"v141-b-g02-E41","location":{"location_id":"src-169a788abb-p08-c1r1__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"10 TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY Fi TABLE III COMPARISONS OF MG BIDDING/","equation_id":null,"figure_id":null,"table_id":"Table II","image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY. Columns: j, t, \\lambda^{P}_{bt} ($/p.u.), P_{jt} (p.u.), \\alpha_{jt} ($/p.u.), \\beta_{jt} ($/p.u.), \\alpha'_{jt} ($/p.u.). Rows: j=1,t=10, \\lambda^{P}_{bt}=0.44, P_{jt}=-0.024, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.44+\\varepsilon; j=2,t=21, \\lambda^{P}_{bt}=0.91, P_{jt}=-0.047, \\alpha_{jt}=0.91, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5; j=2,t=14, \\lambda^{P}_{bt}=0.66, P_{jt}=0.026, \\alpha_{jt}=0.66, \\beta_{jt}=0.5, \\alpha'_{jt}=0.66-\\varepsilon; j=3,t=3, \\lambda^{P}_{bt}=0.44, P_{jt}=0.022, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5."}]},{"constraint_id":"v141-c-R002-C006","kind":"mathematical","role":"supporting","statement":"For an extracting microgrid (P_j^{min} \u003c= P_{jt} \u003c 0) with marginal cost above the DLMP (beta_jt > lambda^P_bt), the modified demand bid price is set equal to the DLMP plus a small positive constant epsilon.","expression":"\\alpha'_{jt}=\\lambda^{P}_{bt}+\\varepsilon, \\quad \\text{for } P_j^{\\min}\\le P_{jt}\u003c0 \\text{ and } \\beta_{jt}>\\lambda^{P}_{bt}","formalization_origin":"source","template_id":null,"members":["bidding.demand","pricing.local","execution.energy_trade"],"variable_refs":["v141-c-R002-x-alpha-prime","v141-c-R002-x-Pjt"],"parameter_refs":["v141-c-R002-theta-beta","v141-c-R002-theta-lambda","v141-c-R002-theta-Pjmin","v141-c-R002-theta-epsilon"],"evidence_ids":["v141-b-g02-E33","v141-b-g02-E34","v141-b-g02-E42"],"ref":"35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C006","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g02-E33","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"6) If P_j^{\\min}\\le P_{jt}\u003c0 and \\beta_{jt}>\\lambda^{P}_{bt}, it indicates that MG j-th is extracting power from DS rather than generating power itself with higher cost. Then MG will bid with price \\alpha'_{jt}=\\lambda^{P}_{bt}+\\varepsilon. The decreasing bid can encourage DS to export more power to MG j-th."},{"evidence_id":"v141-b-g02-E34","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"It is noted that \\varepsilon is a very small positive constant, e.g., 10^{-5}."},{"evidence_id":"v141-b-g02-E42","location":{"location_id":"src-169a788abb-p08-c1r4__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"The DLMP (λPbt) and marginal cost (βjt) and the power ex- th change between MG and DS (Pjt) are give","equation_id":null,"figure_id":null,"table_id":"Table II","image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"The MG1 at 10:00 am extracts power from DS. \\beta_{1,10}>\\lambda^{P}_{30,10}, the bid with decreasing price is 0.44+\\varepsilon. For MG2 at 21:00 pm, \\beta_{2,21}\u003c\\lambda^{P}_{13,21}, the fix offer is 0.5 to maintain its profit. For MG2 at 14:00 pm, \\beta_{2,14}\u003c\\lambda^{P}_{13,14}, the increasing offer is 0.66-\\varepsilon. For MG3 at 3:00 am, the \\beta_{3,3}>\\lambda^{P}_{21,3}, the fixed offer price is set at 0.5."}]},{"constraint_id":"v141-c-R008-C001","kind":"mathematical","role":"core","statement":"The local distribution-system market-clearing model restricts PCC power exchanges to its feasible set, including exchange capacity bounds. Scope: MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM.","expression":"P_{it}^{\\min}\\le P_{it}\\le P_{it}^{\\max},\\quad Q_{it}^{\\min}\\le Q_{it}\\le Q_{it}^{\\max},\\quad \\forall t,\\ \\forall i\\in J,L,M,N","formalization_origin":"source","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":["x_participant_active_it","x_participant_reactive_it"],"parameter_refs":["theta_pmin_it","theta_pmax_it","theta_qmin_it","theta_qmax_it"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12","v141-b-g01-E16"],"ref":"35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C001","source_rule_id":"v141-c-R008","evidence":[{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-pricing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The DLMPs (λPbt) are endogenously generated from the lower-level programming model (8)–(16) (LLPM), and the MG uses DLMPs as the base bidding/offering price λPb′jt. The real power and reactive power exchange at PCC belong to the feasible set defined by the LLPM as in constraint (8)."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-169a788abb-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"p p g g the feasible set deﬁned by the LLPM as in constraint (8). The LLPM presents the distribution","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The LLPM presents the distribution system market clearing problem with the objective to maximize the social welfare (8), which consists of four terms. The first three terms represent the total cost for the DS: operation cost from DS-owned DGs, power exchange with MG, and the cost of extracting power from utility power system. The last item is total benefits obtained by supplying power to customers. Constraint (9) and (10) guarantee that the DGs’ outputs, MGs power exchange, utility extraction, and load requirement are within a capacity range. The constraints (11)–(16) are DistFlow equations that can be used to describe the complex power flows at each node for DS. Constraints (11) and (12) are real power injection and reactive power injection at each node."},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-169a788abb-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"j m l ce. ar- P itmin ≤Pit ≤P itmax : μpitmin , μpitmax , e if ∀t, ∀i ∈J, L, M, N (9) al- Qmin it ≤Q","equation_id":"Eqs. (9)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"P^{min}_{it} \\le P_{it} \\le P^{max}_{it} : \\mu^{p min}_{it}, \\mu^{p max}_{it}, \\forall t, \\forall i \\in J,L,M,N (9) \\quad Q^{min}_{it} \\le Q_{it} \\le Q^{max}_{it} : \\mu^{q min}_{(.)t}, \\mu^{q max}_{(.)t}, \\forall t, \\forall i \\in J,L,M,N (10)"}]},{"constraint_id":"v141-c-R008-C002","kind":"mathematical","role":"core","statement":"Real and reactive MG power balances must ensure that DG generation supplies the entire load and the power exchange at the PCC. Scope: MG real and reactive power balances governing exchanges at the PCC.","expression":"\\sum_{k}P_{kt}=D^{P}_{jt}+P_{jt},\\quad \\sum_{k}Q_{kt}=D^{Q}_{jt}+Q_{jt},\\quad \\forall t,\\ \\forall k\\in K_j,\\ \\forall j\\in J","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_pcc_active_jt","x_pcc_reactive_jt","x_gen_active_kt","x_gen_reactive_kt"],"parameter_refs":["theta_dp_jt","theta_dq_jt"],"evidence_ids":["v141-b-g01-E18","v141-b-g01-E14"],"ref":"35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C002","source_rule_id":"v141-c-R008","evidence":[{"evidence_id":"v141-b-g01-E18","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The objective function of the upper level programming model (ULPM) is to minimize power generation cost of microgrids, power exchange cost at point of common coupling and load shedding cost. The power exchange cost is negative when MGs are extracting power from the distribution system or positive when MGs are exporting power to the DS. Dispatchable generators in MG are subject to real power output capacity constraint (2), reactive power capacity output constraint (3), ramp up rate (4) and ramp down rate (5). Real power balance equations (6) and reactive power balance equations (7) together ensure that the power generated by DGs is used to supply the entire load and the power exchange at PCC."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-169a788abb-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 35, NO. 1, JANUARY 2020 our Pkt = DPjt + Pjt, ∀t, ∀k ∈Kj, ∀","equation_id":"Eqs. (6)-(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\sum_k P_{kt} = D^P_{jt} + P_{jt}, \\forall t, \\forall k \\in K_j, \\forall j \\in J (6) \\quad \\sum_k Q_{kt} = D^Q_{jt} + Q_{jt}, \\forall t, k \\in K_j, \\forall j \\in J (7)"}]},{"constraint_id":"v141-c-R008-C003","kind":"mathematical","role":"core","statement":"Both real and reactive MG exchange bounds are scaled by the binary variable controlling the working-mode switch. Scope: MG–DS real and reactive power exchanges in Case2. Condition: Case2 contingency study of switching between grid-connected and islanded operation.","expression":"\\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le \\rho_{jt}P_{it}^{\\max},\\quad \\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le \\rho_{jt}Q_{it}^{\\max},\\quad \\forall t,\\forall i\\in J","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_islanding_rho_jt","x_participant_active_it","x_participant_reactive_it"],"parameter_refs":["theta_pmin_it","theta_pmax_it","theta_qmin_it","theta_qmax_it"],"evidence_ids":["v141-b-g02-E43","v141-b-g03-e003"],"ref":"35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C003","source_rule_id":"v141-c-R008","evidence":[{"evidence_id":"v141-b-g02-E43","location":{"location_id":"src-169a788abb-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"ads p p p p y p , and especially in the infancy of MG industry deployment. G3 Case2:Thiscasestudiest","equation_id":"Eqs. (54)-(56)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T-\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours. \\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le\\rho_{jt}P_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (54)\\\\ \\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le\\rho_{jt}Q_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (55)\\\\ \\sum_t \\rho_{jt}=T-\\tau\\ \\ \\forall i\\in J \\quad (56)"},{"evidence_id":"v141-b-g03-e003","location":{"location_id":"src-169a788abb-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"10","section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"ads p p p p y p , and especially in the infancy of MG industry deployment. G3 Case2:Thiscasestudiest","equation_id":"Eqs. (54)-(56)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T -\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours.\n\\rho_{jt}P_{it}^{\\min} \\le P_{it} \\le \\rho_{jt}P_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{54}\n\\rho_{jt}Q_{it}^{\\min} \\le Q_{it} \\le \\rho_{jt}Q_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{55}\n\\sum_{t}\\rho_{jt}=T-\\tau \\quad \\forall i \\in J \\tag{56}"}]}],"variables":[{"variable_id":"v141-c-R002-x-Pjt","symbol":"P_{jt}","meaning":"Real power exchange of microgrid j with the distribution system at the PCC in period t; negative values denote extraction from the DS (demand/bid side), positive values denote export (offer side).","kind":"operational","domain":"real; extraction interval for the bid cases is P_j^{min} \u003c= P_{jt} \u003c 0","unit":"p.u.","indices":["j","t"],"evidence_ids":["v141-b-g02-E26","v141-b-g02-E32","v141-b-g02-E33","v141-b-g02-E42"],"source_rule_id":"v141-c-R002","declaration_ref":"35-microgrid_pool_strategy::v141-c-R002::x::v141-c-R002-x-Pjt"},{"variable_id":"v141-c-R002-x-alpha-prime","symbol":"\\alpha'_{jt}","meaning":"Adjusted MG bidding/offering price submitted to the distribution system in period t under the modified strategy; for an extracting MG it is a demand bid price.","kind":"operational","domain":"real price in $/p.u.","unit":"$/p.u.","indices":["j","t"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E32","v141-b-g02-E33","v141-b-g02-E41"],"source_rule_id":"v141-c-R002","declaration_ref":"35-microgrid_pool_strategy::v141-c-R002::x::v141-c-R002-x-alpha-prime"},{"variable_id":"x_pcc_active_jt","symbol":"P_{jt}","meaning":"Real power exchange of microgrid j at the PCC with the distribution system in time t; positive/negative direction follows the source convention that the exchange cost is negative when the MG extracts power and positive when it exports.","kind":"operational","domain":"real-valued","unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14","v141-b-g01-E18"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_pcc_active_jt"},{"variable_id":"x_pcc_reactive_jt","symbol":"Q_{jt}","meaning":"Reactive power exchange of microgrid j at the PCC with the distribution system in time t.","kind":"operational","domain":"real-valued","unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14","v141-b-g01-E18"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_pcc_reactive_jt"},{"variable_id":"x_participant_active_it","symbol":"P_{it}","meaning":"Real power output/exchange variable for participant category i in time t, printed over i in J,L,M,N in the LLPM capacity constraints; for i in J this is the MG PCC exchange term in the source's i-indexed notation.","kind":"operational","domain":"real-valued; i in J,L,M,N","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_participant_active_it"},{"variable_id":"x_participant_reactive_it","symbol":"Q_{it}","meaning":"Reactive power output/exchange variable for participant category i in time t, printed over i in J,L,M,N in the LLPM capacity constraints; for i in J this is the MG PCC reactive exchange term in the source's i-indexed notation.","kind":"operational","domain":"real-valued; i in J,L,M,N","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_participant_reactive_it"},{"variable_id":"x_gen_active_kt","symbol":"P_{kt}","meaning":"Real power output of MG generation unit k in time t.","kind":"operational","domain":"real-valued; k in K_j","unit":null,"indices":["k","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_gen_active_kt"},{"variable_id":"x_gen_reactive_kt","symbol":"Q_{kt}","meaning":"Reactive power output of MG generation unit k in time t.","kind":"operational","domain":"real-valued; k in K_j","unit":null,"indices":["k","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_gen_reactive_kt"},{"variable_id":"x_islanding_rho_jt","symbol":"\\rho_{jt}","meaning":"Binary variable indicating the working-mode/islanding state of MG j in time t; source states it controls the MG working-mode switch in Case2.","kind":"operational","domain":"{0,1}","unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g02-E43","v141-b-g03-e003"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::x::x_islanding_rho_jt"}],"parameters":[{"parameter_id":"v141-c-R002-theta-beta","symbol":"\\beta_{jt}","meaning":"MG j's marginal operation cost in period t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/p.u.","indices":["j","t"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E41","v141-b-g02-E42"],"source_rule_id":"v141-c-R002","declaration_ref":"35-microgrid_pool_strategy::v141-c-R002::theta::v141-c-R002-theta-beta"},{"parameter_id":"v141-c-R002-theta-lambda","symbol":"\\lambda^{P}_{bt}","meaning":"Distribution locational marginal price (real-power dual) at node b in period t, used as price feedback/input to MG demand-bid adjustment.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/p.u.","indices":["b","t"],"evidence_ids":["v141-b-g02-E15","v141-b-g02-E28","v141-b-g02-E41"],"source_rule_id":"v141-c-R002","declaration_ref":"35-microgrid_pool_strategy::v141-c-R002::theta::v141-c-R002-theta-lambda"},{"parameter_id":"v141-c-R002-theta-Pjmin","symbol":"P_j^{\\min}","meaning":"Minimum real-power bound for MG j's PCC exchange, used as the lower endpoint of the extraction interval in the bid cases.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"p.u.","indices":["j"],"evidence_ids":["v141-b-g02-E32","v141-b-g02-E33"],"source_rule_id":"v141-c-R002","declaration_ref":"35-microgrid_pool_strategy::v141-c-R002::theta::v141-c-R002-theta-Pjmin"},{"parameter_id":"v141-c-R002-theta-epsilon","symbol":"\\varepsilon","meaning":"Very small positive constant used in the modified demand-bid price; source gives e.g. 10^{-5}.","value":{"kind":"text","number_value":null,"text_value":"very small positive constant; e.g. 10^{-5}"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E33","v141-b-g02-E34"],"source_rule_id":"v141-c-R002","declaration_ref":"35-microgrid_pool_strategy::v141-c-R002::theta::v141-c-R002-theta-epsilon"},{"parameter_id":"theta_dp_jt","symbol":"D^{P}_{jt}","meaning":"Real power consumption/load of the j-th MG in time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::theta::theta_dp_jt"},{"parameter_id":"theta_dq_jt","symbol":"D^{Q}_{jt}","meaning":"Reactive power consumption/load of the j-th MG in time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::theta::theta_dq_jt"},{"parameter_id":"theta_pmin_it","symbol":"P^{\\min}_{it}","meaning":"Minimum real power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (54).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::theta::theta_pmin_it"},{"parameter_id":"theta_pmax_it","symbol":"P^{\\max}_{it}","meaning":"Maximum real power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (54).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::theta::theta_pmax_it"},{"parameter_id":"theta_qmin_it","symbol":"Q^{\\min}_{it}","meaning":"Minimum reactive power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (55).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::theta::theta_qmin_it"},{"parameter_id":"theta_qmax_it","symbol":"Q^{\\max}_{it}","meaning":"Maximum reactive power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (55).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"],"source_rule_id":"v141-c-R008","declaration_ref":"35-microgrid_pool_strategy::v141-c-R008::theta::theta_qmax_it"}]}],"source_definitions":[{"unit_id":"35-microgrid_pool_strategy::v141-a-M01::execution.energy_trade","stage":"L5","subtype":"pcc_exchange_feasibility","projection_status":"clear","target_definition":"The MG PCC exchanges P_{jt} and Q_{jt} are constrained by capacity limits and by Σ_kP_{kt}=D^P_{jt}+P_{jt} and Σ_kQ_{kt}=D^Q_{jt}+Q_{jt}. A negative active-power value denotes purchase and a positive value denotes outward delivery. Case2 scales the upper and lower bounds of the source expressions P_{it} and Q_{it} (i∈J) by ρ_{jt}∈{0,1}; when ρ_{jt}=0, the exchange is zero.","form_kind":"mathematical","identity_fields":["Object: active- and reactive-power exchange quantities at the grid boundary","Core relation: the exchange quantities simultaneously satisfy local generation-consumption balance and the boundary capacity conditions","Mode relation: the binary operating mode controls the feasible range of exchange","Output: PCC exchange quantities satisfying the constraints"],"variation_fields":["Interface entities: MG and DS; interface location: PCC","Balance inputs: MG-internal DG output and active- and reactive-power load","Active-power sign: import is negative and export is positive","Case2 extension: grid-connected and islanded switching","The mode constraint retains the index notation of the source expressions ρ_{jt} and i∈J","Capacity and operating-mode conditions belong to the optimization model"],"constraint_refs":["35-microgrid_pool_strategy::v141-c-R002::v141-c-R002-C002","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C001","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C002","35-microgrid_pool_strategy::v141-c-R008::v141-c-R008-C003"],"paper_id":"35-microgrid_pool_strategy","mechanism_id":"v141-a-M01","function":"execution.energy_trade","template_code":"PGR"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/210"});
